<script setup lang="ts">import{reactive,ref}from'vue';import type{FormInstance,FormRules}from'element-plus';import{ElMessage}from'element-plus';import{saveLogisticsConfig}from'@/api/logistics';import type{LogisticsConfig}from'@/types/logistics';const emit=defineEmits<{(e:'success'):void}>();const visible=ref(false),saving=ref(false),formRef=ref<FormInstance>();const form=reactive<LogisticsConfig>({name:'',code:'',tracking_url:'',status:1,sort:0,remark:''});const rules:FormRules={name:[{required:true,message:'请输入物流公司名称'}]};const open=(row?:LogisticsConfig)=>{Object.assign(form,row?{...row}:{uid:undefined,name:'',code:'',tracking_url:'',status:1,sort:0,remark:''});visible.value=true};const submit=async()=>{await formRef.value?.validate();saving.value=true;try{await saveLogisticsConfig(form);ElMessage.success('保存成功');visible.value=false;emit('success')}finally{saving.value=false}};defineExpose({open})</script>
<template><el-dialog v-model="visible" :title="form.uid?'修改物流配置':'新增物流配置'" width="620px"><el-form ref="formRef" :model="form" :rules="rules" label-width="110px"><el-form-item label="物流公司" prop="name"><el-input v-model="form.name" maxlength="100"/></el-form-item><el-form-item label="物流编码"><el-input v-model="form.code" maxlength="64" placeholder="用于对接第三方物流查询接口"/></el-form-item><el-form-item label="查询地址"><el-input v-model="form.tracking_url" placeholder="物流查询页面地址"/></el-form-item><el-form-item label="状态"><el-radio-group v-model="form.status"><el-radio-button :value="1">启用</el-radio-button><el-radio-button :value="2">停用</el-radio-button></el-radio-group></el-form-item><el-form-item label="排序"><el-input-number v-model="form.sort" :min="0"/></el-form-item><el-form-item label="备注"><el-input v-model="form.remark" type="textarea" :rows="3" maxlength="255"/></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" :loading="saving" @click="submit">保存</el-button></template></el-dialog></template>
